describe("形参与推断接收者走同一张形参表", () => {
  it.each(CELLS)("%s 接收者 %s", async (_shape, src, messages) => {
    expect(await diags(src)).toEqual(messages === "（收）" ? [] : messages.split(" || "));
  });
});
